814:fn terminate_process_group(pid: u32, step_id: &str) -> Result<(), UniversalExecError> {
815:    let pgid = i32::try_from(pid).map_err(|_| {
816:        UniversalExecError::new(
817:            UniversalExecErrorCode::ToolFailed,
818:            format!("timed-out step {step_id} has an invalid process identity"),
819:            None,
820:            false,
821:        )
822:    })?;
823:    let result = unsafe { libc::kill(-pgid, libc::SIGKILL) };
824:    if result == 0 {
825:        return Ok(());
826:    }
827:    let error = std::io::Error::last_os_error();
828:    if error.raw_os_error() == Some(libc::ESRCH) {
829:        return Ok(());
830:    }
831:    Err(UniversalExecError::new(
832:        UniversalExecErrorCode::ToolFailed,
833:        format!("cannot terminate process group for timed-out step {step_id}: {error}"),
834:        None,
835:        false,
836:    ))
837:}
